args.sql:
select p.payment_id, r.amount as raw, p.amount as parsed
from stg_payments p join raw_payments r using (payment_id)
where r.amount like '€%' order by p.payment_id limit 10

select p.payment_id, r.amount as raw, p.amount as parsed
from stg_payments p join raw_payments r using (payment_id)
where r.amount not like '€%' and p.amount > 1000 order by p.amount desc limit 20

select p.payment_id, r.amount as raw, p.amount as parsed
from stg_payments p join raw_payments r using (payment_id)
where r.amount like '€%' or r.amount in ('399.92','188.00','18.40') order by p.payment_id limit 12

